#!/bin/sh
# Builds index.html from src/. Run from this folder: sh build.sh
cd "$(dirname "$0")"
{ printf '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Rugby Manager 26/27</title>\n<link rel="manifest" href="manifest.webmanifest">\n<meta name="theme-color" content="#0a1026">\n<link rel="apple-touch-icon" href="icon-192.png">\n<link rel="icon" href="icon-192.png">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Saira+Condensed:wght@400;700&display=swap" rel="stylesheet">\n<style>\n'; cat src/style.css; printf '</style>\n</head>\n<body>\n<div id="app"></div>\n<script>\n'; cat src/data.js src/engine.js src/ui.js; printf "</script>\n<script>if ('serviceWorker' in navigator && location.protocol === 'https:') navigator.serviceWorker.register('sw.js').catch(function () {});</script>\n</body>\n</html>\n"; } > index.html
